"""Resolve crafting prerequisites using observed live recipes rather than fixed costs."""
import math
from brain.logic import decision, inventory_count


def ensure_item(state, player, item, count, experience=None, trail=()):
    """Plan the first missing dependency; return None once count items are held.

    Smelt metals and gather raw resources, recursively resolve enabled item recipes,
    and wait for native crafting. Cycles, locked recipes and fluid ingredients are
    explicit blocked decisions. Products with multiple outputs are counted correctly.
    """
    held = inventory_count(player,item)
    if held >= count:
        return None
    if player.get('crafting_queue'):
        return decision('crafting','Wait for the native crafting batch.',{'kind':'wait','duration':2})
    if item in ('iron-plate','copper-plate'):
        from brain.research_rules.smelting import ensure_plates
        return ensure_plates(state,player,item,count,experience)
    if item in ('iron-ore','copper-ore','coal','stone'):
        from brain.logic import mining_decision
        return mining_decision(state,player,item,experience,count-held)
    if item == 'wood':
        from brain.action_library.gathering.mine_wood import mine_wood
        return mine_wood(state,player,count-held)
    if item in trail:
        return decision('blocked','Cyclic recipe dependency: '+item)
    recipe = state.get('recipes',{}).get(item)
    if not recipe or not recipe.get('enabled'):
        return decision('blocked','Recipe is not unlocked: '+item)
    output = sum(p.get('amount',0) for p in recipe['products'] if p['name']==item)
    if output <= 0:
        return decision('blocked','Recipe has no measured output: '+item)
    crafts = math.ceil((count-held)/output)
    for ingredient in recipe['ingredients']:
        if ingredient.get('type','item') != 'item':
            return decision('blocked','Handcrafting fluid recipes is unsupported: '+item)
        plan = ensure_item(state,player,ingredient['name'],ingredient['amount']*crafts,
                           experience,(*trail,item))
        if plan:
            return plan
    return decision('craft_'+item,'Handcraft the required batch of '+item,
                    {'kind':'craft','player':player['name'],'recipe':item,'count':crafts})

"""Python navigation planning stays bounded and does not overshoot axis changes."""
import unittest
from brain.execution import walking_instruction


class WalkingPlanTest(unittest.TestCase):
    def test_confident_clear_leg_runs_longer_than_two_seconds(self):
        plan=walking_instruction({'x':0,'y':0},{'x':100,'y':0},2,9,confident=True)
        self.assertEqual(plan['duration'],8)

    def test_mining_duration_estimates_only_the_requested_batch(self):
        from brain.execution import mining_duration
        self.assertAlmostEqual(mining_duration(3,1,.5,0,100,1,True),6.05)
        self.assertEqual(mining_duration(16,1,.5,0,100,1,False),2)

    def test_long_moves_choose_cardinal_direction_and_bounded_duration(self):
        plan=walking_instruction({'x':0,'y':0},{'x':100,'y':10},2,9)
        self.assertEqual(plan, {'direction':'east','duration':2})

    def test_diagonal_leg_stops_when_shorter_axis_is_aligned(self):
        plan=walking_instruction({'x':0,'y':0},{'x':-6,'y':4},1,9)
        self.assertEqual(plan['direction'],'southwest')
        self.assertAlmostEqual(plan['duration'],4*2**0.5/9)

    def test_already_in_reach_does_not_start_walking(self):
        self.assertEqual(walking_instruction({'x':0,'y':0},{'x':1,'y':0},2,9)['duration'],0)

    def test_paused_game_cannot_produce_a_timed_movement(self):
        with self.assertRaises(ValueError):
            walking_instruction({'x':0,'y':0},{'x':10,'y':0},2,0)

"""Bounded tree queries must choose nearby harvestable trees, not a truncated far chunk."""
import unittest
from unittest.mock import patch


class TreeSearchTest(unittest.TestCase):
    def test_dense_forest_is_requeried_to_find_a_nearby_tree(self):
        from brain.observation import tree_targets
        def query(actor,filters,fields,limit=512):
            near={'name':'tree-01','position':{'x':8,'y':0},'minable':True,'wood_yield':4}
            far={'name':'tree-01','position':{'x':100,'y':0},'minable':True,'wood_yield':4}
            return {'truncated':filters['radius']>16,'entities':[far] if filters['radius']>16 else [near]}
        with patch('brain.observation.read_entities',side_effect=query):
            trees=tree_targets(14,{'x':0,'y':0})
        self.assertEqual(trees[0]['position'],{'x':8,'y':0})

"""Recipe dependencies, trigger gates, research progress and machine interactions."""
import unittest
from brain.research_rules.recipes import ensure_item
from brain.research_rules.bootstrap import first_research
from brain.research_rules.smelting import transfer
from scripts.test_brain import state
from brain.research_rules.power import steam_layout


class ResearchRulesTest(unittest.TestCase):
    def test_two_product_recipe_does_not_double_material_requirements(self):
        s=state({'copper-plate':1})
        s['recipes']={'copper-cable':{'enabled':True,'ingredients':[{'name':'copper-plate','amount':1}],
                                    'products':[{'name':'copper-cable','amount':2}]}}
        plan=ensure_item(s,s['players'][0],'copper-cable',2)
        self.assertEqual(plan['action'],{'kind':'craft','player':'alice','recipe':'copper-cable','count':1})

    def test_locked_recipes_are_not_bypassed(self):
        s=state(); s['recipes']={'lab':{'enabled':False}}
        self.assertEqual(ensure_item(s,s['players'][0],'lab',1)['phase'],'blocked')

    def test_trigger_research_requires_real_production_before_power_build(self):
        s=state({'iron-plate':100})
        s['technologies']={'steam-power':{'researched':False}}
        s['iron_produced']=0
        self.assertNotEqual(first_research(s,player_name='alice')['phase'],'plan_power')

    def test_automation_completion_is_observed_not_fabricated(self):
        s=state(); s['technologies']={'automation':{'researched':True}}
        self.assertEqual(first_research(s,player_name='alice')['phase'],'complete')

    def test_machine_transfer_requires_close_approach(self):
        s=state(); e={'name':'stone-furnace','unit_number':1,'position':{'x':8,'y':0}}
        self.assertEqual(transfer(s['players'][0],e,'fuel','coal',8)['kind'],'move')

    def test_existing_wood_fuel_is_preserved_and_research_can_start(self):
        s=state({'coal':8});parts=steam_layout({'x':0,'y':0},'north')
        s['power_layout']={'entities':parts}
        s['entities']=[{**p,'surface':'nauvis','force':'player','unit_number':i,
                        'energy':1000 if p['role']=='lab' else 0,
                        'inventories':{'fuel':{'wood':9}} if p['role']=='boiler' else {}}
                       for i,p in enumerate(parts,1)]
        s['technologies']={name:{'researched':True} for name in ('steam-power','electronics','automation-science-pack')}
        self.assertEqual(first_research(s,player_name='alice')['phase'],'start_research')
